class CacheMixin:
    def __init__(self, *args, **kwargs):
        self.cache = {}
        super().__init__()  # note: no args/kwargs forwarded

class Repository(CacheMixin, Base):
    def __init__(self, db_url):
        super().__init__(db_url)

class Base:
    def __init__(self):
        self.value = self.compute()

    def compute(self):
        return 1

class Derived(Base):
    def compute(self):
        return 2

print(Derived().value)

